// Structural check of the agent's JSON. Drops malformed proposals and
// recomputes "external" from attendee domains instead of trusting the model.
const ctx = $('Build context').first().json.ctx;
const out = $input.first().json.output || {};
const ALLOWED = ['create_event', 'reschedule_event', 'cancel_event', 'propose_times'];
const STATUSES = ['ok', 'needs_input', 'no_action'];
const domains = (ctx.company_domains || []).map(d => String(d).toLowerCase());
const isInternal = (email) => domains.includes((String(email || '').toLowerCase().split('@')[1]) || '');
const notes = [];
const raw = Array.isArray(out.proposals) ? out.proposals : [];
const valid = [];
raw.forEach((p, i) => {
  const label = 'proposal ' + (i + 1);
  if (!p || typeof p !== 'object') { notes.push(label + ' dropped: not an object'); return; }
  if (!ALLOWED.includes(p.type)) { notes.push(label + ' dropped: unknown type ' + p.type); return; }
  if (!p.summary) { notes.push(label + ' dropped: missing summary'); return; }
  if ((p.type === 'reschedule_event' || p.type === 'cancel_event') && !p.event_id) {
    notes.push(label + ' dropped: missing event_id'); return;
  }
  if (p.type !== 'cancel_event') {
    const start = DateTime.fromISO(String(p.start || ''), { zone: ctx.tz });
    const end = DateTime.fromISO(String(p.end || ''), { zone: ctx.tz });
    if (!start.isValid || !end.isValid || end <= start) { notes.push(label + ' dropped: invalid start/end'); return; }
  }
  const attendees = Array.isArray(p.attendees) ? p.attendees.map(String) : [];
  valid.push(Object.assign({}, p, {
    attendees,
    affects: Array.isArray(p.affects) ? p.affects : attendees,
    external: attendees.some(a => !isInternal(a))
  }));
});
return [{ json: {
  status: STATUSES.includes(out.status) ? out.status : 'ok',
  results: out.results || {},
  proposals: valid,
  notes: [out.notes].concat(notes).filter(Boolean).join(' | ')
} }];

// Policy check: timed proposals must be in the future and inside working hours.
const ctx = $('Build context').first().json.ctx;
const data = $input.first().json;
const now = DateTime.now().setZone(ctx.tz);
const wh = ctx.working_hours || { start: '09:30', end: '18:30' };
const toMin = (hhmm) => { const parts = String(hhmm).split(':'); return Number(parts[0]) * 60 + Number(parts[1] || 0); };
const whStart = toMin(wh.start);
const whEnd = toMin(wh.end);
const notes = data.notes ? [data.notes] : [];
const kept = [];
let weekend = 0;
data.proposals.forEach((p, i) => {
  if (p.type === 'cancel_event') { kept.push(p); return; }
  const start = DateTime.fromISO(p.start, { zone: ctx.tz }).setZone(ctx.tz);
  const end = DateTime.fromISO(p.end, { zone: ctx.tz }).setZone(ctx.tz);
  const label = 'proposal ' + (i + 1) + ' (' + p.summary + ')';
  if (start < now) { notes.push(label + ' dropped: starts in the past'); return; }
  if (start.weekday >= 6 || end.weekday >= 6) { weekend++; notes.push(label + ' dropped: WEEKEND - ' + start.toFormat('cccc d LLL') + ' is a ' + start.toFormat('cccc') + '; meetings are not scheduled on Saturday or Sunday'); return; }
  const s = start.hour * 60 + start.minute;
  const e = end.hour * 60 + end.minute;
  if (!start.hasSame(end, 'day') || s < whStart || e > whEnd) {
    notes.push(label + ' dropped: outside working hours'); return;
  }
  kept.push(p);
});
let status = data.status;
if (weekend && !kept.length) {
  status = 'needs_input';
  notes.push('Flagged as weekend: the requested time is on Saturday or Sunday. Pick a weekday (Monday to Friday) instead.');
}
return [{ json: { status, results: data.results, proposals: kept, notes: notes.join(' | ') } }];

// One item per proposal: which invitees to check and for which slot.
// The user's own addresses and calendars are not checked here.
const d = $input.first().json;
const ctx = $('Build context').first().json.ctx;
const self = [ctx.user_email].concat(ctx.calendars || []).filter(Boolean).map(s => String(s).toLowerCase());
const fallbackCal = (ctx.calendars && ctx.calendars[0]) || 'primary';
const now = DateTime.now().setZone(ctx.tz);
const props = d.proposals || [];
if (!props.length) {
  return [{ json: { idx: -1, check_ids: [], query_ids: [fallbackCal], timeMin: now.toISO(), timeMax: now.plus({ minutes: 30 }).toISO() } }];
}
return props.map((p, idx) => {
  const timed = p.type !== 'cancel_event' && p.start && p.end;
  const check_ids = timed
    ? [...new Set((p.attendees || []).map(a => String(a).trim().toLowerCase()).filter(a => a && !self.includes(a)))]
    : [];
  return { json: {
    idx, check_ids,
    query_ids: check_ids.length ? check_ids : [fallbackCal],
    timeMin: timed ? p.start : now.toISO(),
    timeMax: timed ? p.end : now.plus({ minutes: 30 }).toISO()
  } };
});

// Keep only options where every invitee is confirmed free.
// Busy invitees, or invitees whose calendar cannot be read, drop the option.
const d = $('Check step').first().json;
const ctx = $('Build context').first().json.ctx;
const self = [ctx.user_email].concat(ctx.calendars || []).filter(Boolean).map(s => String(s).toLowerCase());
const preps = $('Prepare invitee check').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const notes = d.notes ? [d.notes] : [];
const kept = [];
let blocked = 0;
(d.proposals || []).forEach((p, idx) => {
  const k = preps.findIndex(x => x.idx === idx);
  const ids = k >= 0 ? (preps[k].check_ids || []) : [];
  if (!ids.length) { kept.push(Object.assign({}, p, { self_emails: self })); return; }
  const cals = (res[k] && res[k].calendars) || {};
  const busy = [];
  const unknown = [];
  ids.forEach(id => {
    const c = cals[id];
    if (!c || (c.errors && c.errors.length)) unknown.push(id);
    else if ((c.busy || []).length) busy.push(id);
  });
  if (busy.length || unknown.length) {
    blocked++;
    const parts = [];
    if (busy.length) parts.push('busy: ' + busy.join(', '));
    if (unknown.length) parts.push('availability could not be checked (calendar not shared): ' + unknown.join(', '));
    notes.push('Option ' + (idx + 1) + ' (' + p.start + ') removed - ' + parts.join('; '));
    return;
  }
  kept.push(Object.assign({}, p, { self_emails: self, invitees_checked: true }));
});
let status = d.status;
if (!kept.length && blocked) {
  status = 'needs_input';
  notes.push('No option has every invitee confirmed free. Ask the invitees to share their calendar free/busy, or suggest times they confirm.');
}
return [{ json: { status, results: d.results, proposals: kept, notes: notes.join(' | ') } }];

const d = $input.first().json;
const proposals = (d.proposals || []).slice(0, 3);
let status = d.status || 'ok';
if (status === 'ok' && proposals.length === 0) status = 'no_action';
return [{ json: { status, results: d.results || {}, proposals, notes: d.notes || '' } }];

const meta = $input.first().json;                 // from Final proposals
const user_id = $('Parse task').first().json.user_id;
const agent = 'scheduler';                         // hard-coded per workflow
const pid = (i) => String($execution.id) + '-' + (i + 1);   // Build response uses the same rule
return meta.proposals.map((p, i) => ({ json: {
  proposal_id: pid(i), user_id, agent,
  action: JSON.stringify(p), summary: p.summary, external: !!p.external, status: 'pending'
} }));

const meta = $('Final proposals').first().json;   // { status, results, proposals, notes }
const pid = (i) => String($execution.id) + '-' + (i + 1);   // same rule as Split proposals
return [{ json: {
  status: meta.status,
  results: meta.results,
  proposed_actions: meta.proposals.map((p, i) => ({
    proposal_id: pid(i), summary: p.summary, affects: p.affects || [], external: !!p.external
  })),
  notes: meta.notes || ''
} }];
